pub(super) fn lookup_string_property(name: &str) -> Option<(&'static [i32], &'static [&'static str])> {
match name {
        "Basic_Emoji" => Some((STRING_PROPERTY_BASIC__EMOJI_CHARACTERS, STRING_PROPERTY_BASIC__EMOJI_STRINGS)),
        "Emoji_Keycap_Sequence" => Some((STRING_PROPERTY_EMOJI__KEYCAP__SEQUENCE_CHARACTERS, STRING_PROPERTY_EMOJI__KEYCAP__SEQUENCE_STRINGS)),
        "RGI_Emoji" => Some((STRING_PROPERTY_R_G_I__EMOJI_CHARACTERS, STRING_PROPERTY_R_G_I__EMOJI_STRINGS)),
        "RGI_Emoji_Flag_Sequence" => Some((STRING_PROPERTY_R_G_I__EMOJI__FLAG__SEQUENCE_CHARACTERS, STRING_PROPERTY_R_G_I__EMOJI__FLAG__SEQUENCE_STRINGS)),
        "RGI_Emoji_Modifier_Sequence" => Some((STRING_PROPERTY_R_G_I__EMOJI__MODIFIER__SEQUENCE_CHARACTERS, STRING_PROPERTY_R_G_I__EMOJI__MODIFIER__SEQUENCE_STRINGS)),
        "RGI_Emoji_Tag_Sequence" => Some((STRING_PROPERTY_R_G_I__EMOJI__TAG__SEQUENCE_CHARACTERS, STRING_PROPERTY_R_G_I__EMOJI__TAG__SEQUENCE_STRINGS)),
        "RGI_Emoji_ZWJ_Sequence" => Some((STRING_PROPERTY_R_G_I__EMOJI__Z_W_J__SEQUENCE_CHARACTERS, STRING_PROPERTY_R_G_I__EMOJI__Z_W_J__SEQUENCE_STRINGS)),
        _ => None,
    }
}
